// Deja el pedido igual venga del formulario o del webhook.
const e = $input.first().json;
const cuerpo = e.body || e;              // el webhook trae los datos en body
const deFormulario = 'Pieza' in cuerpo;
const pieza = deFormulario ? String(cuerpo['Pieza']).split(' · ')[0] : cuerpo.id_pieza;
const num = (v) => (v === undefined || v === null || v === '' ? null : Number(v));
return [{ json: {
  origen: deFormulario ? 'formulario' : 'webhook',
  recibido_en: new Date().toISOString(),
  cliente: String(deFormulario ? cuerpo['Tu nombre o usuario'] : cuerpo.nombre || '').trim().slice(0, 60),
  canal: deFormulario ? cuerpo['Canal'] : cuerpo.canal,
  id_pieza: pieza,
  cantidad: num(deFormulario ? cuerpo['Cantidad'] : cuerpo.cantidad),
  a_medida: {
    tecnologia: deFormulario ? cuerpo['Tecnología (solo a medida)'] : cuerpo.tecnologia,
    material_cantidad: num(deFormulario ? cuerpo['Gramos o ml (solo a medida)'] : cuerpo.material_cantidad),
    horas_placa: num(deFormulario ? cuerpo['Horas de impresión (solo a medida)'] : cuerpo.horas_placa),
  },
  comentario: String((deFormulario ? cuerpo['Comentario'] : cuerpo.comentario) || '').slice(0, 300),
} }];

// Costeo de una pieza impresa en 3D: la misma fórmula de scripts/costeo.py.
// Este código va dentro del nodo «Calcular cotización» del flujo de n8n
// (scripts/armar_flujo.py lo copia tal cual) y las pruebas lo comparan con Python y SQL.

function leerCsv(texto) {
  // CSV sencillo con comillas dobles (como los que escribe Python).
  const filas = [];
  let fila = [], campo = '', comillas = false;
  const t = texto.replace(/^﻿/, '');
  for (let i = 0; i < t.length; i++) {
    const c = t[i];
    if (comillas) {
      if (c === '"' && t[i + 1] === '"') { campo += '"'; i++; }
      else if (c === '"') comillas = false;
      else campo += c;
    } else if (c === '"') comillas = true;
    else if (c === ',') { fila.push(campo); campo = ''; }
    else if (c === '\n' || c === '\r') {
      if (c === '\r' && t[i + 1] === '\n') i++;
      fila.push(campo); campo = '';
      if (fila.length > 1 || fila[0] !== '') filas.push(fila);
      fila = [];
    } else campo += c;
  }
  if (campo !== '' || fila.length) { fila.push(campo); filas.push(fila); }
  const [encabezado, ...resto] = filas;
  return resto.map((f) => Object.fromEntries(encabezado.map((h, i) => [h, f[i]])));
}

function tablaTarifas(filas) {
  const t = {};
  for (const f of filas) t[f.parametro] = Number(f.valor);
  return t;
}

function costoUnitario(pieza, t) {
  const cantidad = Number(pieza.material_cantidad);
  const horas = Number(pieza.horas_placa);
  const ppp = Number(pieza.piezas_por_placa);
  const acabado = Number(pieza.minutos_acabado);
  if (!(ppp > 0) || !(cantidad >= 0) || !(horas >= 0) || !(acabado >= 0)) {
    throw new Error('Datos de la pieza fuera de rango');
  }
  let material, insumosPlaca, potencia, maquinaHora, tasa;
  if (pieza.tecnologia === 'Resina') {
    material = cantidad * (1 + t.resina_soportes_pct) * t.resina_precio_litro / 1000;
    insumosPlaca = t.alcohol_ml_por_placa * t.alcohol_precio_litro / 1000
      + t.guantes_pares_por_placa * t.guantes_precio_par
      + t.papel_por_placa
      + t.fep_precio / t.fep_placas_vida;
    [potencia, maquinaHora, tasa] = [t.resina_potencia_w, t.resina_maquina_hora, t.resina_tasa_fallas];
  } else if (pieza.tecnologia === 'FDM') {
    material = cantidad * (1 + t.fdm_purga_pct) * t.filamento_precio_kg / 1000;
    insumosPlaca = t.fdm_insumos_por_placa;
    [potencia, maquinaHora, tasa] = [t.fdm_potencia_w, t.fdm_maquina_hora, t.fdm_tasa_fallas];
  } else {
    throw new Error('Tecnología desconocida: ' + pieza.tecnologia);
  }
  const insumos = insumosPlaca / ppp;
  const energia = horas * potencia / 1000 * t.energia_precio_kwh / ppp;
  const maquina = horas * maquinaHora / ppp;
  const manoObra = (t.preparacion_min_por_placa / ppp + acabado) / 60 * t.mano_obra_hora;
  const base = material + insumos + energia + maquina + manoObra;
  const fallas = base * tasa;
  return {
    material, insumos, energia, maquina, mano_obra: manoObra, fallas,
    costo_total: material + insumos + energia + maquina + manoObra + fallas,
  };
}

function precioSugerido(costo, t, comision) {
  const divisor = 1 - t.margen_objetivo - (comision || 0);
  if (divisor <= 0) throw new Error('Margen más comisión no pueden sumar 100 % o más');
  const paso = t.redondeo_precio;
  // Se quita el ruido de coma flotante antes del techo (igual efecto que en Python).
  return Math.ceil(Number((costo / divisor / paso).toFixed(9))) * paso;
}

function cotizar(pieza, cantidad, canal, t, canales) {
  if (!Number.isInteger(cantidad) || cantidad < 1) throw new Error('La cantidad debe ser un entero mayor que cero');
  if (!(canal in canales)) throw new Error('Canal desconocido: ' + canal);
  const c = costoUnitario(pieza, t);
  const comision = canales[canal];
  const precioUnitario = precioSugerido(c.costo_total, t, comision);
  const total = precioUnitario * cantidad;
  const costoTotal = c.costo_total * cantidad;
  const comisionValor = total * comision;
  return {
    costo_unitario: c.costo_total,
    precio_unitario: precioUnitario,
    cantidad,
    total,
    comision: comisionValor,
    ganancia: total - costoTotal - comisionValor,
    margen_pct: (total - costoTotal - comisionValor) / total,
  };
}

if (typeof module !== 'undefined') {
  module.exports = { leerCsv, tablaTarifas, costoUnitario, precioSugerido, cotizar };
}

// ---------------------------------------------------------------------------
// Pegamento de n8n: junta las filas de los 3 CSV y calcula la cotización.
const pedido = $('Configuración').first().json;
const filas = $input.all().map((i) => i.json);
const tarifas = tablaTarifas(filas.filter((f) => 'parametro' in f));
const catalogo = filas.filter((f) => 'id_pieza' in f && 'tecnologia' in f);
const canales = Object.fromEntries(filas.filter((f) => 'comision_pct' in f).map((f) => [f.canal, Number(f.comision_pct)]));
const origenDatos = filas.length && filas.every((f) => f.origen_datos === 'ficticio') ? 'ficticio' : 'real';

const fallo = (motivo) => [{ json: { ...pedido, ok: false, motivo, origen_datos: origenDatos } }];
if (!tarifas.margen_objetivo || !catalogo.length || !Object.keys(canales).length) {
  throw new Error('No se pudieron leer tarifas.csv, piezas.csv o canales.csv');
}

let pieza;
if (pedido.id_pieza === 'A medida') {
  const m = pedido.a_medida || {};
  if (!['Resina', 'FDM'].includes(m.tecnologia)) return fallo('Pieza a medida sin tecnología');
  if (!(m.material_cantidad > 0) || !(m.horas_placa > 0)) return fallo('Pieza a medida sin gramos/ml u horas');
  if (m.material_cantidad > 2000 || m.horas_placa > 72) return fallo('Pieza a medida fuera de rango: revisar a mano');
  pieza = { id_pieza: 'MEDIDA', nombre: 'Pieza a medida', tecnologia: m.tecnologia,
    material_cantidad: m.material_cantidad, horas_placa: m.horas_placa, piezas_por_placa: 1,
    minutos_acabado: tarifas.minutos_acabado_a_medida };
} else {
  pieza = catalogo.find((p) => p.id_pieza === pedido.id_pieza);
  if (!pieza) return fallo('La pieza no está en el catálogo');
}
if (!Number.isInteger(pedido.cantidad) || pedido.cantidad < 1 || pedido.cantidad > 500) {
  return fallo('Cantidad inválida (debe ser un entero entre 1 y 500)');
}
if (!(pedido.canal in canales)) return fallo('Canal desconocido');

const cot = cotizar(pieza, pedido.cantidad, pedido.canal, tarifas, canales);
const pesos = (n) => '$' + Math.round(n).toLocaleString('es-CO').replace(/,/g, '.');
const dias = Number(pedido.dias_entrega);
const prompt = [
  'Atiendes un taller de impresión 3D en Colombia. Escribe la respuesta para ' + (pedido.cliente || 'el cliente') + ', que escribió por ' + pedido.canal + '.',
  'Usa SOLO estas cifras, tal cual, sin agregar otras:',
  '- Pieza: ' + pieza.nombre,
  '- Cantidad: ' + cot.cantidad,
  '- Precio por unidad: ' + pesos(cot.precio_unitario),
  '- Total: ' + pesos(cot.total),
  '- Entrega: ' + dias + ' días hábiles',
  'Reglas: máximo 4 frases, tutea, tono amable y concreto, sin emojis, sin inventar descuentos, envíos ni fechas.',
  pedido.comentario ? 'El cliente comentó: "' + pedido.comentario + '" (respóndelo solo si se puede sin agregar cifras).' : '',
].filter(Boolean).join('\n');
const plantilla = 'Hola' + (pedido.cliente ? ' ' + pedido.cliente : '') + ', gracias por escribirnos. '
  + cot.cantidad + ' x ' + pieza.nombre + ' quedan en ' + pesos(cot.precio_unitario) + ' cada una, '
  + pesos(cot.total) + ' en total. La entrega es en ' + dias + ' días hábiles. ¿Te lo separamos?';

return [{ json: { ...pedido, ok: true, pieza: pieza.nombre, tecnologia: pieza.tecnologia, ...cot,
  precio_texto: pesos(cot.precio_unitario), total_texto: pesos(cot.total), prompt, plantilla,
  origen_datos: origenDatos } }];

// Control de la IA: cada número del borrador debe estar en la cotización.
const c = $('Calcular cotización').first().json;
const r = $input.first().json;
let borrador = String(r.response || '').trim();
// Algunos modelos piensan en voz alta entre <think>…</think>: se quita.
borrador = borrador.replace(/<think>[\s\S]*?<\/think>/g, '').trim();
const permitidos = new Set([c.cantidad, Math.round(c.precio_unitario), Math.round(c.total), Number(c.dias_entrega)]
  .map((n) => String(n)));
for (const n of (String(c.pieza) + ' ' + String(c.cliente)).match(/\d+/g) || []) permitidos.add(n);   // «Miniatura 32 mm», «andrea_92»
const limpio = borrador.replace(/\b3D\b/gi, '');
const numeros = (limpio.match(/\d[\d.,]*/g) || []).map((n) => n.replace(/[.,](?=\d{3}\b)/g, '').replace(/[.,]$/, ''));
const extranos = numeros.filter((n) => !permitidos.has(n));
const tieneTotal = numeros.includes(String(Math.round(c.total)));
let ia_ok = borrador.length > 0 && extranos.length === 0 && tieneTotal;
let nota_ia = ia_ok ? 'Borrador de la IA revisado: todas las cifras cuadran'
  : !borrador ? 'La IA no devolvió texto: se usó la plantilla'
  : extranos.length ? 'La IA puso cifras que no están en la cotización (' + extranos.join(', ') + '): se usó la plantilla'
  : 'La IA no puso el total: se usó la plantilla';
const texto = ia_ok ? borrador : c.plantilla;
return [{ json: { ...c, borrador: texto, ia_ok, nota_ia } }];

// Ollama no respondió después de los reintentos: se sigue con la plantilla.
const c = $('Calcular cotización').first().json;
return [{ json: { ...c, borrador: c.plantilla, ia_ok: false,
  nota_ia: 'Ollama no respondió después de 3 intentos: se usó la plantilla' } }];

// Aviso para el dueño del taller: deja el enlace de aprobación en registro/pendientes.csv.
// (Aquí se puede conectar Telegram o correo, con la credencial guardada en n8n, nunca en el repo.)
const c = $input.first().json;
const r = { fecha_hora: new Date().toISOString(), id_ejecucion: $execution.id, cliente: c.cliente,
  pieza: c.pieza, cantidad: c.cantidad, total: Math.round(c.total), enlace_aprobacion: $execution.resumeFormUrl };
const esc = (v) => { const s = v === undefined || v === null ? '' : String(v);
  return /[",\n\r]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s; };
const linea = ["fecha_hora", "id_ejecucion", "cliente", "pieza", "cantidad", "total", "enlace_aprobacion"].map((c) => esc(r[c])).join(',') + '\n';
return [{ json: { ...c, linea, resumen_para_el_dueno: '**' + c.cliente + '** pidió ' + c.cantidad + ' x ' + c.pieza
  + ' por ' + c.canal + '. Costo ' + Math.round(c.costo_unitario) + ' c/u, precio ' + c.precio_texto
  + ', total ' + c.total_texto + ', margen ' + Math.round(c.margen_pct * 100) + ' %.\n\n' + c.nota_ia
  + '\n\nBorrador:\n\n' + c.borrador } }];

// Arma la línea del registro con la decisión del dueño (o el motivo del rechazo automático).
const valido = $('¿Pedido válido?').first().json.ok === true;
const c = valido ? $('Avisar al dueño').first().json : $('Calcular cotización').first().json;
const f = valido ? $input.first().json : {};
let decision, mensaje;
if (!valido) { decision = 'Inválido'; mensaje = c.motivo; }
else if (f['Decisión'] === 'Aprobar') { decision = 'Aprobado'; mensaje = c.borrador; }
else if (f['Decisión'] === 'Corregir') {
  const t = String(f['Texto corregido'] || '').trim();
  decision = t ? 'Corregido' : 'Aprobado sin cambios (corrección vacía)'; mensaje = t || c.borrador; }
else if (f['Decisión'] === 'Rechazar') { decision = 'Rechazado'; mensaje = ''; }
else { decision = 'Sin respuesta en 24 h'; mensaje = ''; }
const r = { fecha_hora: new Date().toISOString(), id_ejecucion: $execution.id, origen: c.origen,
  cliente: c.cliente, canal: c.canal, id_pieza: c.id_pieza, pieza: c.pieza || '', cantidad: c.cantidad,
  costo_unitario: valido ? Math.round(c.costo_unitario) : '', precio_unitario: valido ? c.precio_unitario : '',
  total: valido ? Math.round(c.total) : '', margen_pct: valido ? Math.round(c.margen_pct * 1000) / 10 : '',
  ia_ok: valido ? c.ia_ok : '', nota_ia: valido ? c.nota_ia : '', decision, mensaje_final: mensaje,
  origen_datos: c.origen_datos };
const esc = (v) => { const s = v === undefined || v === null ? '' : String(v);
  return /[",\n\r]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s; };
const linea = ["fecha_hora", "id_ejecucion", "origen", "cliente", "canal", "id_pieza", "pieza", "cantidad", "costo_unitario", "precio_unitario", "total", "margen_pct", "ia_ok", "nota_ia", "decision", "mensaje_final", "origen_datos"].map((c) => esc(r[c])).join(',') + '\n';
return [{ json: { ...r, linea } }];
